using System.Globalization;

var ordersDb = new Database();
var billingDb = new Database();
var orders = new OrderService(ordersDb);
var consumer = new InboxConsumer(billingDb);
var broker = new FlakyBroker(consumer, seed: 42);
var relay = new OutboxRelay(ordersDb, broker, batchSize: 10);

var placed = new Dictionary<Guid, decimal>();
for (var i = 1; i <= 50; i++)
{
    var id = Guid.NewGuid();
    placed[id] = i * 10m;
    orders.PlaceOrder(id, i * 10m);
}

// Client retries of the first five orders: same order id, must not create new outbox rows.
foreach (var (id, amount) in placed.Take(5))
    Check("duplicate PlaceOrder is a no-op", !orders.PlaceOrder(id, amount));

Check("rejected order leaves no trace", Throws(() => orders.PlaceOrder(Guid.NewGuid(), 0m)));
Check("failed transaction rolls back", RollsBack(ordersDb));
Check("one outbox row per order", ordersDb.Execute(s => s.Outbox.Count) == placed.Count);

var rounds = 0;
while (ordersDb.Execute(s => s.Outbox.Any(r => !r.Published)) && rounds++ < 1_000)
    await relay.PublishPendingAsync(CancellationToken.None);

Check("all outbox rows published", ordersDb.Execute(s => s.Outbox.All(r => r.Published)));
Check("broker delivered duplicates", broker.Deliveries > placed.Count);
Check("each message applied once", billingDb.Execute(s => s.Inbox.Count) == placed.Count);
Check("ledger matches orders", billingDb.Execute(s =>
    placed.All(p => s.Ledger.TryGetValue(p.Key, out var v) && v == p.Value)));
Console.WriteLine($"deliveries={broker.Deliveries}, orders={placed.Count}, relay rounds={rounds}");

static void Check(string name, bool ok) => Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {name}");

static bool RollsBack(Database db)
{
    var before = db.Execute(s => (s.Orders.Count, s.Outbox.Count));
    try
    {
        db.Execute<int>(s =>
        {
            s.Orders[Guid.NewGuid()] = 1m;
            throw new InvalidOperationException("crash before the outbox row is written");
        });
    }
    catch (InvalidOperationException) { }
    return db.Execute(s => (s.Orders.Count, s.Outbox.Count)) == before;
}

static bool Throws(Action a)
{
    try { a(); return false; }
    catch (ArgumentOutOfRangeException) { return true; }
}

public sealed record OutboxMessage(long Sequence, Guid MessageId, string Type, string Payload);

public sealed record OutboxRow(OutboxMessage Message, bool Published);

public sealed record OrderPlaced(Guid OrderId, decimal Amount)
{
    public string ToPayload() => string.Create(CultureInfo.InvariantCulture, $"{OrderId}|{Amount}");

    public static OrderPlaced FromPayload(string payload)
    {
        var parts = payload.Split('|');
        return new OrderPlaced(Guid.Parse(parts[0]), decimal.Parse(parts[1], CultureInfo.InvariantCulture));
    }
}

public sealed class BrokerException(string message) : Exception(message);

public interface IBroker
{
    Task PublishAsync(OutboxMessage message, CancellationToken ct);
}

/// <summary>Stand-in for one relational database: Execute is serialised and atomic.</summary>
public sealed class DbState
{
    public Dictionary<Guid, decimal> Orders { get; private init; } = new();
    public List<OutboxRow> Outbox { get; private init; } = new();
    public HashSet<Guid> Inbox { get; private init; } = new();
    public Dictionary<Guid, decimal> Ledger { get; private init; } = new();
    public long NextSequence { get; set; } = 1;

    public DbState Clone() => new()
    {
        Orders = new(Orders),
        Outbox = new(Outbox),
        Inbox = new(Inbox),
        Ledger = new(Ledger),
        NextSequence = NextSequence,
    };
}

public sealed class Database
{
    private readonly object _gate = new();
    private DbState _state = new();

    public T Execute<T>(Func<DbState, T> work)
    {
        lock (_gate)
        {
            var draft = _state.Clone();
            var result = work(draft); // if work throws, the draft is discarded: rollback
            _state = draft;           // commit
            return result;
        }
    }
}

public sealed class OrderService(Database db)
{
    /// <returns>true if the order was created, false if it already existed (idempotent retry).</returns>
    public bool PlaceOrder(Guid orderId, decimal amount)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(amount);
        return db.Execute(s =>
        {
            if (s.Orders.ContainsKey(orderId)) return false;
            s.Orders[orderId] = amount;
            var message = new OutboxMessage(
                s.NextSequence++,
                Guid.NewGuid(),
                nameof(OrderPlaced),
                new OrderPlaced(orderId, amount).ToPayload());
            s.Outbox.Add(new OutboxRow(message, Published: false)); // same transaction as the order
            return true;
        });
    }
}

public sealed class OutboxRelay(Database db, IBroker broker, int batchSize)
{
    /// <returns>Number of messages published and marked in this pass.</returns>
    public async Task<int> PublishPendingAsync(CancellationToken ct)
    {
        // Short read transaction; never hold a transaction open across a network call.
        var batch = db.Execute(s => s.Outbox
            .Where(r => !r.Published)
            .OrderBy(r => r.Message.Sequence)
            .Take(batchSize)
            .Select(r => r.Message)
            .ToList());

        var published = 0;
        foreach (var message in batch)
        {
            try
            {
                await broker.PublishAsync(message, ct);
            }
            catch (BrokerException)
            {
                break; // keep order: do not skip ahead of an unpublished message
            }

            db.Execute(s =>
            {
                var i = s.Outbox.FindIndex(r => r.Message.MessageId == message.MessageId);
                s.Outbox[i] = s.Outbox[i] with { Published = true };
                return 0;
            });
            published++;
        }

        return published;
    }
}

public sealed class InboxConsumer(Database db)
{
    /// <returns>true if the effect was applied, false if the message was a duplicate.</returns>
    public bool Handle(OutboxMessage message)
    {
        if (message.Type != nameof(OrderPlaced))
            throw new InvalidOperationException($"Unknown message type {message.Type}");

        var evt = OrderPlaced.FromPayload(message.Payload);

        return db.Execute(s =>
        {
            if (!s.Inbox.Add(message.MessageId)) return false; // dedupe and effect commit together
            s.Ledger[evt.OrderId] = s.Ledger.GetValueOrDefault(evt.OrderId) + evt.Amount;
            return true;
        });
    }
}

public sealed class FlakyBroker(InboxConsumer consumer, int seed) : IBroker
{
    private readonly Random _random = new(seed);

    public int Deliveries { get; private set; }

    public Task PublishAsync(OutboxMessage message, CancellationToken ct)
    {
        ct.ThrowIfCancellationRequested();
        var roll = _random.NextDouble();
        if (roll < 0.2) throw new BrokerException("connection refused"); // not delivered

        Deliveries++;
        consumer.Handle(message);

        if (roll < 0.5) throw new BrokerException("ack lost"); // delivered, but the relay thinks it failed
        return Task.CompletedTask;
    }
}

en.note:
## What it is

Messaging decouples a producer from consumers in **time** (the consumer may be down), **load** (the queue absorbs bursts) and **knowledge** (the producer need not know who listens). Two delivery shapes:

- **Queue (point-to-point).** Each message is processed by **one** of N *competing consumers*; adding consumers adds throughput.
- **Publish/subscribe.** Each **subscription** gets its own copy; inside one subscription, consumers compete again. "Queue vs pub/sub" is therefore a question of how many logical receivers there are, not of persistence or push vs pull.

## How the big three differ underneath

**RabbitMQ: smart broker, per-message state.** Producers publish to an *exchange* (`direct`, `topic`, `fanout`, `headers`) that routes copies into queues via bindings, which is how pub/sub is built. Consumers get messages pushed, bounded by the **prefetch** (`basic.qos`), and ack/nack each one. A message is gone once acked; replay is not a feature. Use **quorum queues** (Raft-replicated) for durability; they count deliveries and can dead-letter after a *delivery limit* (since RabbitMQ 4.0 the default limit is 20). A **dead-letter exchange** (DLX) receives rejected, expired or over-limit messages. RabbitMQ *streams* (3.9+) add a log-style, replayable structure.

**Kafka: dumb broker, smart consumer, durable log.** A topic is split into **partitions**, each an append-only log; records with the same key go to the same partition, so **ordering is per partition**, never per topic. A *consumer group* assigns each partition to exactly one member, so **parallelism is capped by the partition count**: extra members sit idle. Consumers track **offsets**; committing an offset acknowledges everything before it. Messages stay for the retention period whether consumed or not, so you can replay, add new consumer groups later, and measure *consumer lag*. Kafka 4.x adds *share groups* (KIP-932, queue-like per-record acks), still maturing.

**SQS: managed queue, pull-based.** *Standard* queues: nearly unlimited throughput, at-least-once, best-effort ordering. *FIFO* queues: ordering per **`MessageGroupId`** (different groups proceed in parallel), deduplication of identical sends within a 5-minute window, lower throughput limits (high-throughput mode raises them). A received message becomes invisible for the **visibility timeout**; if not deleted in time it reappears, which is SQS's redelivery mechanism. A *redrive policy* moves a message to a DLQ after `maxReceiveCount` receives. Fan-out is done with SNS (or EventBridge) in front of several queues.

## Ordering, poison messages, DLQs

- **Ordering is expensive.** Global order means one consumer. Ask what must actually be ordered (usually per entity), key by it (Kafka key, FIFO group id, consistent-hash exchange) and accept that a retry or redelivery can still reorder unless the consumer checks versions.
- **Poison message**: one that fails deterministically (bad schema, a bug). Retrying it forever burns CPU and, in an ordered log, **blocks the whole partition** (head-of-line blocking). Bound retries, separate transient from permanent errors, then move the message aside: a DLQ, or retry topics with increasing delays and a final DLQ for Kafka (Kafka itself has no built-in consumer DLQ; frameworks and Kafka Connect provide one).
- **A DLQ is a process, not a bin.** Alert on its depth, keep the original headers and the exception, and have a tested redrive path.

## What an interviewer probes

Delivery semantics (at-most-once = ack before processing; at-least-once = ack after; "exactly-once" = at-least-once plus idempotency), why consumer count above partition count does nothing in Kafka, what happens when processing outlives the visibility timeout or the RabbitMQ consumer ack timeout, and how you pick between the three.

## Common misconceptions

- "Pub/sub messages are not persisted": Kafka topics and SNS-to-SQS subscriptions are durable.
- "More consumers always means more throughput": not past the partition count, and not for ordered FIFO groups.
- "Prefetch 1 with several consumers keeps order": competing consumers process in parallel, and a nack/requeue reorders.

## Code: Kafka consumer committing after processing

```csharp
var config = new ConsumerConfig
{
    BootstrapServers = "kafka:9092",
    GroupId = "billing",
    EnableAutoCommit = false,                  // commit only after the effect is durable
    AutoOffsetReset = AutoOffsetReset.Earliest
};
using var consumer = new ConsumerBuilder<string, string>(config).Build();
consumer.Subscribe("orders");
while (!ct.IsCancellationRequested)
{
    var result = consumer.Consume(ct);
    try
    {
        await handler.HandleAsync(result.Message, ct);   // idempotent
    }
    catch (Exception ex) when (IsPermanent(ex))
    {
        await deadLetters.ProduceAsync("orders.dlq", result.Message, ct); // do not block the partition
    }
    consumer.Commit(result);                    // at-least-once
}
```
